 public void ValidatePlayerUi(){Search.Text="246";var item=PlayerList.Items.Cast<PlayerItem>().First(p=>p.Id==246);PlayerList.SelectedItem=item;ShowPlayerCore();var shoe=AppearanceGrid.Rows.Cast<DataGridViewRow>().Single(r=>Convert.ToString(r.Tag)=="number:shoetypecode");var cell=(DataGridViewComboBoxCell)shoe.Cells[1];cell.Value=cell.Items.Cast<string>().First(v=>ParseValue(v)==116);if(GridNumber("shoecolorcode1")!=0)throw new Exception("UI: variante de botines incompatible.");var rating=Fields.Rows.Cast<DataGridViewRow>().Single(r=>Convert.ToString(r.Tag)=="number:overallrating");rating.Cells[1].Value="93";Search.Text="Cristiano Ronaldo";var edited=State.Db.Rows("players")[item.Index];if(GameDatabase.Number(edited,"shoetypecode")!=116||GameDatabase.Number(edited,"shoecolorcode1")!=0||GameDatabase.Number(edited,"overallrating")!=93)throw new Exception("UI: cambios no preparados al filtrar.");if(Selected==null||Selected.Id!=20801)throw new Exception("UI: seleccion tras filtro.");}
