  var outer=new SplitContainer{Dock=DockStyle.Fill,Width=1200,SplitterDistance=310};page.Controls.Add(outer);var left=new Panel{Dock=DockStyle.Fill,Padding=new Padding(8)};outer.Panel1.Controls.Add(left);
