  foreach(var grid in new[]{Fields,AppearanceGrid}){grid.Dock=DockStyle.Fill;grid.AllowUserToAddRows=grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.Columns.Add("field","Campo");grid.Columns.Add("value","Valor");grid.Columns[0].ReadOnly=true;grid.Columns[0].FillWeight=100;grid.Columns[1].FillWeight=105;grid.EditingControlShowing+=(s,e)=>EditorPalette.Apply(e.Control,DarkTheme);grid.DataError+=(s,e)=>{e.ThrowException=false;Note("Selecciona un valor valido del catalogo.");};}
