  var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=74};actions.Controls.Add(Button("Preparar jugador",ApplyPlayer));actions.Controls.Add(Button("Ver botas",()=>{if(Selected==null)return;Shoes.FocusId((int)GridNumber("shoetypecode"));Tabs.SelectedIndex=3;}));actions.Controls.Add(Button("Ver cara",()=>{if(Selected==null)return;Faces.FocusId(Selected.Id);Tabs.SelectedIndex=1;}));actions.Controls.Add(Button("Restaurar jugador",RestoreSelectedPlayer));actions.Controls.Add(new Label{Text="Los cambios se preparan al cambiar de jugador. Guardar cambios escribe con respaldo.",AutoSize=true});right.Controls.Add(columns);right.Controls.Add(PlayerTitle);right.Controls.Add(actions);
  League.SelectedIndexChanged+=(s,e)=>{if(!Loading)Run(UpdateTeams);};Team.SelectedIndexChanged+=(s,e)=>{if(!Loading)Run(FilterPlayers);};Search.TextChanged+=(s,e)=>{if(!Loading)Run(FilterPlayers);};
