 static long ParseValue(object value){string text=Convert.ToString(value);int p=text.IndexOf(" — ",StringComparison.Ordinal);if(p>=0)text=text.Substring(0,p);long n;if(!Int64.TryParse(text,out n))throw new ArgumentException("Selecciona un valor numerico valido.");return n;}
 long GridNumber(string key){foreach(DataGridViewRow row in AppearanceGrid.Rows)if(Convert.ToString(row.Tag)=="number:"+key)return ParseValue(row.Cells[1].Value);return Selected==null?0:GameDatabase.Number(State.Db.Rows("players")[Selected.Index],key);}
 string LabelFor(string key){string label;return Labels.TryGetValue(key,out label)?label:key;}
 void AttributeRow(string key,object value,bool text){int i=Fields.Rows.Add(L.T(LabelFor(key)),Convert.ToString(value));Fields.Rows[i].Cells[0].Tag=LabelFor(key);Fields.Rows[i].Tag=(text?"name:":"number:")+key;if(!text){var f=State.Db.Tables["players"].Fields.Single(x=>x.Name==key);Fields.Rows[i].Cells[1].ToolTipText=L.T("Rango: ")+f.Low+" .. "+f.High;}}
 void AppearanceRow(string key,string label,long value,Dictionary<int,string> options){int index=AppearanceGrid.Rows.Add(L.T(label),"");var row=AppearanceGrid.Rows[index];row.Cells[0].Tag=label;row.Tag="number:"+key;SetOptions(row,options,value);}
 void SetOptions(DataGridViewRow row,Dictionary<int,string> options,long value){var cell=new EditorComboCell{DisplayStyle=DataGridViewComboBoxDisplayStyle.DropDownButton,FlatStyle=FlatStyle.Flat};foreach(var item in options.OrderBy(p=>p.Key))cell.Items.Add(item.Key+" — "+L.T(item.Value));if(!options.ContainsKey((int)value))cell.Items.Add(value+" — "+L.T("Original (no identificado)"));row.Cells[1]=cell;cell.Value=cell.Items.Cast<string>().First(s=>ParseValue(s)==value);}
 static Dictionary<int,string> ColorOptions(IEnumerable<int> colors){return colors.ToDictionary(c=>c,c=>"Color "+c);}
 void UpdateColors(string code){if(Selected==null)return;string key=code=="shoetypecode"?"shoecolorcode1":"accessorycolourcode"+code.Substring("accessorycode".Length);var row=AppearanceGrid.Rows.Cast<DataGridViewRow>().SingleOrDefault(r=>Convert.ToString(r.Tag)=="number:"+key);if(row==null)return;int id=(int)GridNumber(code);int[] allowed=State.Appearance.Colors(code,id);if(allowed.Length==0)throw new ArgumentException("No hay variantes disponibles.");long old=ParseValue(row.Cells[1].Value);bool previous=ShowingPlayer;ShowingPlayer=true;try{SetOptions(row,ColorOptions(allowed),allowed.Contains((int)old)?old:allowed[0]);}finally{ShowingPlayer=previous;}}
 void ShowPlayerCore(){ShowingPlayer=true;try{Selected=PlayerList.SelectedItem as PlayerItem;Fields.Rows.Clear();AppearanceGrid.Rows.Clear();if(Selected==null){PlayerTitle.Text=L.T("Selecciona un jugador.");SetShoeImage(null);return;}PlayerTitle.Text=Selected.Name+" · ID "+Selected.Id;var names=State.Db.Rows("playernames")[Selected.NameIndex];foreach(string key in new[]{"firstname","surname","commonname","playerjerseyname"})AttributeRow(key,names[key],true);
   var row=State.Db.Rows("players")[Selected.Index];foreach(var f in State.Db.Tables["players"].Fields.Where(f=>AppearanceRules.AttributeFields.Contains(f.Name)).OrderBy(f=>f.Name=="overallrating"?0:f.Name=="potential"?1:2).ThenBy(f=>LabelFor(f.Name)))AttributeRow(f.Name,row[f.Name],false);
   int shoe=(int)GameDatabase.Number(row,"shoetypecode"),color=(int)GameDatabase.Number(row,"shoecolorcode1");AppearanceRow("shoetypecode","Modelo de botines",shoe,State.Appearance.ShoeColors.Keys.ToDictionary(c=>c,c=>"Botines ID "+c));AppearanceRow("shoecolorcode1","Variante de botines",color,ColorOptions(State.Appearance.Colors("shoetypecode",shoe)));
   AppearanceRow("jerseystylecode","Camiseta",GameDatabase.Number(row,"jerseystylecode"),new Dictionary<int,string>{{0,"Por dentro"},{1,"Por fuera"}});AppearanceRow("jerseysleevelengthcode","Mangas",GameDatabase.Number(row,"jerseysleevelengthcode"),new Dictionary<int,string>{{0,"Cortas"},{1,"Largas"}});AppearanceRow("haswintergloves","Guantes de invierno",GameDatabase.Number(row,"haswintergloves"),new Dictionary<int,string>{{0,"No"},{1,"Si"}});
   for(int i=1;i<=4;i++){int id=(int)GameDatabase.Number(row,"accessorycode"+i);AppearanceRow("accessorycode"+i,"Accesorio "+i,id,AppearanceRules.Accessories);AppearanceRow("accessorycolourcode"+i,"Color accesorio "+i,GameDatabase.Number(row,"accessorycolourcode"+i),ColorOptions(State.Appearance.Colors("accessorycode"+i,id)));}
  }finally{ShowingPlayer=false;}RefreshShoePreview();}
 void SetShoeImage(Image image){var old=ShoePreview.Image;ShoePreview.Image=image;if(old!=null)old.Dispose();}
 void RefreshShoePreview(){if(Selected==null)return;int id=(int)GridNumber("shoetypecode"),color=(int)GridNumber("shoecolorcode1");ShoeCaption.Text=L.T("Botines ")+id+" / color "+color;string name="data/sceneassets/shoe/shoe_"+id+"_"+color+"_textures.rx2";var asset=State.Assets.FirstOrDefault(a=>a.Name.Equals(name,StringComparison.OrdinalIgnoreCase));if(asset==null){SetShoeImage(null);ShoeCaption.Text+=" — Variante ausente";return;}try{var textures=Texture.Parse(State.Read(asset));var t=textures.Where(x=>x.Format==18).OrderByDescending(x=>x.Width*x.Height).FirstOrDefault()??textures.FirstOrDefault();SetShoeImage(t==null?null:t.Preview());}catch(InvalidDataException){SetShoeImage(null);}}
 void ApplyPlayerCore(){if(Selected==null||ShowingPlayer)return;Fields.EndEdit();AppearanceGrid.EndEdit();var numbers=new Dictionary<string,long>();var names=new Dictionary<string,string>();foreach(var grid in new[]{Fields,AppearanceGrid})foreach(DataGridViewRow row in grid.Rows){string tag=Convert.ToString(row.Tag),key=tag.Substring(tag.IndexOf(':')+1),text=Convert.ToString(row.Cells[1].Value);if(tag.StartsWith("name:")){var f=State.Db.Tables["playernames"].Fields.Single(x=>x.Name==key);if(System.Text.Encoding.UTF8.GetByteCount(text)>Math.Min(255,f.Depth/8))throw new ArgumentException(key+": nombre demasiado largo.");names[key]=text;}else{var f=State.Db.Tables["players"].Fields.Single(x=>x.Name==key);long value=ParseValue(row.Cells[1].Value);if(value<f.Low||value>f.High)throw new ArgumentException(LabelFor(key)+": rango "+f.Low+" .. "+f.High);numbers[key]=value;}}
  var original=State.Db.Rows("players")[Selected.Index];State.Appearance.Validate(original,numbers);bool changed=false;foreach(var item in numbers)if(GameDatabase.Number(original,item.Key)!=item.Value){State.Db.SetNumber("players",Selected.Index,item.Key,item.Value);changed=true;}var nameRow=State.Db.Rows("playernames")[Selected.NameIndex];foreach(var item in names)if(Convert.ToString(nameRow[item.Key])!=item.Value){State.Db.SetName(Selected.NameIndex,item.Key,item.Value);changed=true;}if(changed){State.DbDirty=true;Note("Jugador preparado con combinaciones verificadas. Pulsa Guardar cambios para aplicarlo.");}
 }
 void RestoreOriginalFiles(){if(State==null)return;if(MessageBox.Show(this,"Restaurar TODOS los BIG/BH originales verificados, incluyendo datos y texturas de TODOS los guardados del editor.\r\n\r\nSe descartaran cambios pendientes. Tus partidas y plantillas no se modifican. ¿Continuar?",Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Note("Localizando originales y verificando respaldos...");Status.Refresh();string root=State.Root;int count=Originals.RestoreAll(root,BackupRoot);LoadGame(root);Note(count==0?"Los 14 BIG/BH ya coinciden con los originales.":"Restauracion completa: "+count+" archivos recuperados; 14 BIG/BH originales verificados.");}
}
